import numpy as np 

def transform (grid :list [list [int ]])->list [list [int ]]:
    """
    Analyzes the input grid to identify patterns of repetition or symmetry.
    The transformation fills gaps (zeros) in rows or columns by borrowing 
    values from other rows or columns that contain the same non-zero pattern.
    """
    # Diagnosis: The previous code was too aggressive; it filled zeros in rows/cols 
    # that were entirely zero (the border/padding) because it didn't check if the 
    # source row/col was actually a valid pattern source. It also failed to 
    # recognize that pattern completion should only occur when a row/col is 
    # a partial match of a complete pattern, not just any non-zero row.

    grid_arr =np .array (grid )
    rows ,cols =grid_arr .shape 
    output =grid_arr .copy ()

    # We iterate multiple times to allow pattern propagation (e.g., row fills column)
    # but we must ensure we only fill zeros that are part of a pattern.
    for _ in range (3 ):
    # 1. Row-based pattern completion
        for r in range (rows ):
        # Skip rows that are entirely zero (padding)
            if np .all (grid_arr [r ]==0 ):
                continue 

            for r_ref in range (rows ):
                if r ==r_ref :
                    continue 
                    # Skip reference rows that are entirely zero
                if np .all (grid_arr [r_ref ]==0 ):
                    continue 

                    # A row 'r' can be filled by 'r_ref' if:
                    # 1. Everywhere 'r' is non-zero, it matches 'r_ref'
                    # 2. 'r' has at least one zero where 'r_ref' has a non-zero
                    # 3. 'r' is not just a subset of 'r_ref' but actually shares a structure

                mask_to_fill =(output [r ]==0 )&(grid_arr [r_ref ]!=0 )
                both_nonzero =(grid_arr [r ]!=0 )&(grid_arr [r_ref ]!=0 )

                # Check if the existing non-zero elements in 'r' match 'r_ref'
                if np .any (mask_to_fill )and np .all (grid_arr [r ][both_nonzero ]==grid_arr [r_ref ][both_nonzero ]):
                # Crucially, we only fill if the non-zero pattern is consistent
                # and we don't accidentally fill the empty border rows.
                    output [r ,mask_to_fill ]=grid_arr [r_ref ,mask_to_fill ]

                    # 2. Column-based pattern completion
        for c in range (cols ):
            if np .all (grid_arr [:,c ]==0 ):
                continue 

            for c_ref in range (cols ):
                if c ==c_ref :
                    continue 
                if np .all (grid_arr [:,c_ref ]==0 ):
                    continue 

                mask_to_fill =(output [:,c ]==0 )&(grid_arr [:,c_ref ]!=0 )
                both_nonzero =(grid_arr [:,c ]!=0 )&(grid_arr [:,c_ref ]!=0 )

                if np .any (mask_to_fill )and np .all (grid_arr [:,c ][both_nonzero ]==grid_arr [:,c_ref ][both_nonzero ]):
                    output [:,c ][mask_to_fill ]=grid_arr [:,c_ref ][mask_to_fill ]

                    # Final pass to ensure we didn't create new non-zero values in the original zero-rows
                    # by checking against the original grid's zero-row mask.
    final_output =output .copy ()
    for r in range (rows ):
        if np .all (grid_arr [r ]==0 ):
            final_output [r ]=0 
    for c in range (cols ):
        if np .all (grid_arr [:,c ]==0 ):
            final_output [:,c ]=0 

    return final_output .tolist ()

